layer.css:
[data-ryt="pitch"] { color: var(--ryt-text); border-left: 3px solid rgb(204, 204, 204); border-radius: 0px; font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.75; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 4px; padding-right: 20px; padding-bottom: 4px; padding-left: 20px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: rgb(105, 105, 105); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { background-color: var(--ryt-surface); border-top: 1px solid var(--ryt-border); border-right: 1px solid var(--ryt-border); border-bottom: 1px solid var(--ryt-border); border-left: 1px solid var(--ryt-border); border-radius: 8px; transition: all }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-bottom: 1px solid rgba(0, 0, 0, 0); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="hero"] h1 { color: rgb(26, 26, 26); font-size: 18.9px; font-weight: 600; font-style: normal; line-height: 1.5; letter-spacing: -0.189px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(26, 26, 26); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: rgb(26, 26, 26); border-bottom: 1px solid rgba(0, 0, 0, 0); border-radius: 0px; font-size: 18px; font-weight: 700; font-style: normal; line-height: 1.6; letter-spacing: -0.18px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(26, 26, 26); text-decoration-thickness: auto; text-underline-offset: auto; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="nav"] a { color: rgb(26, 26, 26); border-bottom: 1px solid rgba(0, 0, 0, 0); border-radius: 0px; font-size: 12.8px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(26, 26, 26); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="category"], [data-ryt="tags"] li { color: var(--ryt-muted); border-bottom: 1px solid rgba(0, 0, 0, 0); border-radius: 0px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="review"] { color: var(--ryt-text); font-size: 14px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-size: 12px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: rgb(26, 26, 26); border-radius: 0px; font-weight: 600; font-style: normal; letter-spacing: -0.189px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(26, 26, 26); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: rgb(26, 26, 26); border-radius: 0px; font-size: 18.9px; font-weight: 600; font-style: normal; line-height: 1.5; letter-spacing: -0.189px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(26, 26, 26); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: rgb(163, 29, 29); outline-color: initial }
[data-ryt="category"]:hover, [data-ryt="tags"] li:hover { color: rgb(163, 29, 29); outline-color: initial; color: rgb(163, 29, 29) }
[data-ryt="nav"] a:hover { color: rgb(163, 29, 29); outline-color: initial }
[data-ryt="brand"]:hover { color: rgb(163, 29, 29); outline-color: initial }
[data-ryt="credit"] a::after, [data-ryt="review"] a::after, [data-ryt="bio"] a::after { content: ""; display: inline-block; width: 12px; height: 12px; margin-left: 3.2px; vertical-align: -0.8px; color: var(--ryt-accent); background-color: var(--ryt-accent); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.75; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: all; -webkit-text-fill-color: var(--ryt-accent) }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: rgb(163, 29, 29); outline-color: initial }
